import hmac
import hashlib
import struct
import time
import os
import base64
from flask import Flask, request, jsonify, g
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = secrets.token_hex(32)

# Token format: base64(header_bytes + payload_bytes + expiry_bytes) + '.' + base64(hmac_sig)
# header: 4 bytes version
# payload: variable length username (null-terminated) + role (null-terminated)
# expiry: 4 bytes unsigned int32 (absolute epoch seconds, valid until 2106)

SECRET = os.environ.get('TOKEN_SECRET', secrets.token_bytes(32))
ADMIN_USERS = {'admin', 'root'}
USER_DB = {}

def constant_time_compare(a, b):
    return hmac.compare_digest(a, b)

def compute_mac(data):
    return hmac.new(SECRET if isinstance(SECRET, bytes) else SECRET.encode(),
                    data, hashlib.sha256).digest()

def create_token(username, role, ttl=3600):
    header = struct.pack('>I', 1)  # version 1
    payload = username.encode('utf-8') + b'\x00' + role.encode('utf-8') + b'\x00'
    # Store expiry as unsigned 32-bit integer (absolute epoch time)
    expiry_time = int(time.time() + ttl)
    if expiry_time > 0xFFFFFFFF:
        raise ValueError("Expiry overflow")
    expiry = struct.pack('>I', expiry_time)
    token_data = header + payload + expiry
    mac = hmac.new(SECRET if isinstance(SECRET, bytes) else SECRET.encode(),
                   token_data, hashlib.sha256).digest()
    token_b64 = base64.urlsafe_b64encode(token_data).decode()
    mac_b64 = base64.urlsafe_b64encode(mac).decode()
    return f"{token_b64}.{mac_b64}"

def verify_token(token_str):
    """Verify token integrity and expiry. Returns (username, role) or raises."""
    try:
        parts = token_str.split('.')
        if len(parts) != 2:
            raise ValueError("Invalid token format")

        token_data = base64.urlsafe_b64decode(parts[0])
        provided_mac = base64.urlsafe_b64decode(parts[1])

        # Verify HMAC first
        expected_mac = hmac.new(SECRET if isinstance(SECRET, bytes) else SECRET.encode(),
                               token_data, hashlib.sha256).digest()
        if not constant_time_compare(expected_mac, provided_mac):
            raise ValueError("Invalid signature")

        # Parse header
        if len(token_data) < 8:  # minimum: 4 header + at least 4 expiry
            raise ValueError("Token too short")

        version = struct.unpack('>I', token_data[:4])[0]
        if version != 1:
            raise ValueError("Unsupported version")

        # Parse payload (find null terminators)
        payload_start = 4
        first_null = token_data.index(b'\x00', payload_start)
        username = token_data[payload_start:first_null].decode('utf-8')

        second_null = token_data.index(b'\x00', first_null + 1)
        role = token_data[first_null + 1:second_null].decode('utf-8')

        # Parse expiry - unsigned 32-bit integer (absolute epoch)
        expiry_bytes = token_data[second_null + 1:second_null + 5]
        if len(expiry_bytes) != 4:
            raise ValueError("Missing expiry")

        expiry_val = struct.unpack('>I', expiry_bytes)[0]  # unsigned int32

        # Simple absolute comparison - no wraparound issues
        current_time = int(time.time())
        if current_time > expiry_val:
            raise ValueError("Token expired")

        return username, role

    except (ValueError, struct.error, UnicodeDecodeError) as e:
        raise ValueError(f"Token verification failed: {e}")

def require_auth(f):
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing authorization'}), 401

        token = auth_header[7:]
        try:
            username, role = verify_token(token)
            g.username = username
            g.role = role
        except ValueError as e:
            return jsonify({'error': str(e)}), 401

        return f(*args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

def require_admin(f):
    def decorated(*args, **kwargs):
        if g.role != 'admin':
            return jsonify({'error': 'Admin required'}), 403
        return f(*args, **kwargs)
    decorated.__name__ = f.__name__
    return decorated

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    if username in USER_DB:
        return jsonify({'error': 'User exists'}), 409

    salt = secrets.token_bytes(16)
    pw_hash = hashlib.pbkdf2_hmac('sha256', data['password'].encode(), salt, 100000)
    role = 'admin' if username in ADMIN_USERS else 'user'
    USER_DB[username] = {'salt': salt, 'hash': pw_hash, 'role': role}

    return jsonify({'status': 'registered'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    if username not in USER_DB:
        # Dummy computation to prevent timing attacks
        hashlib.pbkdf2_hmac('sha256', data['password'].encode(), b'x' * 16, 100000)
        return jsonify({'error': 'Invalid credentials'}), 401

    user = USER_DB[username]
    pw_hash = hashlib.pbkdf2_hmac('sha256', data['password'].encode(), user['salt'], 100000)

    if not constant_time_compare(pw_hash, user['hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = create_token(username, user['role'])
    return jsonify({'token': token}), 200

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    return jsonify({'username': g.username, 'role': g.role})

@app.route('/api/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    users = {k: {'role': v['role']} for k, v in USER_DB.items()}
    return jsonify(users)

@app.route('/api/admin/secret', methods=['GET'])
@require_auth
@require_admin
def get_secret():
    return jsonify({'secret': app.config['SECRET_KEY']})

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000, debug=False)
